import assert from "node:assert/strict";
import {readFileSync,writeFileSync} from "node:fs";
import {parseDailyCap,parseReleaseCap} from "../../dex/base-price-provider/budget.mjs";
import {publicReleaseReady} from "../../dex/base-price-provider/worker.mjs";
const {PUBLIC_DAILY_CAP:daily,PUBLIC_TOTAL_CAP:total,PUBLIC_RELEASE_HOURS:hours}=process.env;
assert.ok(parseDailyCap(daily)>=5&&parseDailyCap(daily)<=100,"Choose daily allocation 5–100, including smoke and previous attempts today");
assert.ok(parseReleaseCap(total)>=parseDailyCap(daily)&&parseReleaseCap(total)<=1000,"Choose absolute cumulative ceiling within confirmed remaining allocation");
assert.match(hours||"",/^(?:[1-9]|1[0-9]|2[0-4])$/,"Choose 1–24 hours");
const base=readFileSync("dex/base-price-provider/wrangler.staging.generated.toml","utf8");
for(const line of ['name = "climboria-base-price-preview"','BASE_INDICATIVE_PRICE_ENABLED = "false"','BASE_PRICE_DAILY_ATTEMPTS = "0"','workers_dev = false','preview_urls = false','routes = [{ pattern = "base-price.climboria.fun", custom_domain = true }]'])assert.ok(base.split("\n").includes(line),"Unexpected disabled baseline");
assert.ok(!/BASE_PRICE_(STAGING|PUBLIC|RELEASE_TOTAL)/.test(base),"Baseline must have no release settings");
const expires=String(Date.now()+Number(hours)*3600000);
const env={BASE_INDICATIVE_PRICE_ENABLED:"true",BASE_PRICE_PUBLIC_RELEASE:"true",BASE_PRICE_STAGING_ONLY:"false",BASE_PRICE_PUBLIC_EXPIRES_AT:expires,BASE_PRICE_DAILY_ATTEMPTS:daily,BASE_PRICE_RELEASE_TOTAL_ATTEMPTS:total};
assert.ok(publicReleaseReady(env),"Release config rejected by same runtime policy");
const replacement=Object.entries(env).map(([k,v])=>k+' = "'+v+'"').join("\n");
const config=base.replace('BASE_INDICATIVE_PRICE_ENABLED = "false"\nBASE_PRICE_DAILY_ATTEMPTS = "0"',replacement);
assert.notEqual(config,base);
writeFileSync("dex/base-price-provider/wrangler.public.generated.toml",config,{flag:"wx"});
console.log("PASS: explicit bounded public indicative release generated; daily="+daily+" absolute cumulative="+total+" expiry="+new Date(Number(expires)).toISOString());
